// @whimtex-effect Samples/Master Tint
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param color _Tint = (1, 1, 1, 1)

float4 ApplyFX(float2 uv,float4 color){return float4(color.rgb*_Tint.rgb,color.a*_Opacity*_Tint.a);}

// @whimtex-effect Samples/Star Glare
// @control(_Opacity)
// @param hidden float _Opacity = 1 [0 .. 1]
// @param enum _Part = 2 { Halo: 0, Rays: 1, Core: 2 }
// @param float _Angle = 24 [-180 .. 180]
// @param float _Size = 1 [0.2 .. 2]
// @param float _RayWidth = 1 [0.3 .. 3]
// @param float _RayLength = 1 [0.3 .. 1.5]

float4 ApplyFX(float2 uv,float4 color){
    float2 p=(uv-.5)/_Size;
    float r=length(p);float a=radians(_Angle);
    float2 q=float2(p.x*cos(a)-p.y*sin(a),p.x*sin(a)+p.y*cos(a));
    float halo=exp(-r*10)*.65+exp(-r*r/.036)*.2;
    float rays=exp(-abs(q.x)*180/_RayWidth-abs(q.y)*13/_RayLength)+exp(-abs(q.y)*230/_RayWidth-abs(q.x)*16/_RayLength);
    float2 s=float2(q.x+q.y,q.y-q.x)*.7071;
    rays+=.30*(exp(-abs(s.x)*300-abs(s.y)*22)+exp(-abs(s.y)*300-abs(s.x)*22));
    float core=exp(-pow(r/.022,2.4))+.6*exp(-r*r/.0013);
    float alpha=_Part<.5?halo:(_Part<1.5?rays:core);
    alpha*=1-smoothstep(.42,.49,length(uv-.5));
    return float4(1,1,1,saturate(alpha)*_Opacity);
}

